const html = "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>KTM-WDC Phase 1 Published</title>\n  <style>\n    :root {\n      color-scheme: light;\n      --ink: #18212f;\n      --muted: #5c6675;\n      --line: #d7dde6;\n      --brand: #b91c1c;\n      --brand-dark: #8f1515;\n      --panel: #ffffff;\n      --soft: #f4f6f8;\n      --ok: #176b45;\n    }\n    * { box-sizing: border-box; }\n    body {\n      margin: 0;\n      background: var(--soft);\n      color: var(--ink);\n      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n      line-height: 1.5;\n    }\n    header {\n      background: linear-gradient(135deg, #991b1b 0%, #273142 100%);\n      color: #fff;\n      padding: 56px 24px 42px;\n    }\n    main {\n      margin: 0 auto;\n      max-width: 1120px;\n      padding: 28px 24px 56px;\n    }\n    .wrap { margin: 0 auto; max-width: 1120px; }\n    .eyebrow {\n      font-size: 13px;\n      font-weight: 800;\n      letter-spacing: .08em;\n      text-transform: uppercase;\n      opacity: .9;\n    }\n    h1 {\n      font-size: clamp(34px, 6vw, 62px);\n      line-height: 1.02;\n      margin: 14px 0 16px;\n      max-width: 900px;\n    }\n    .lead {\n      font-size: 18px;\n      max-width: 840px;\n      opacity: .92;\n    }\n    .actions {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 12px;\n      margin-top: 28px;\n    }\n    a.button {\n      align-items: center;\n      border: 1px solid rgba(255,255,255,.35);\n      color: #fff;\n      display: inline-flex;\n      font-weight: 800;\n      justify-content: center;\n      min-height: 44px;\n      padding: 10px 16px;\n      text-decoration: none;\n    }\n    a.button.primary {\n      background: #fff;\n      border-color: #fff;\n      color: var(--brand-dark);\n    }\n    .grid {\n      display: grid;\n      gap: 18px;\n      grid-template-columns: repeat(3, minmax(0, 1fr));\n      margin-top: -46px;\n    }\n    .panel {\n      background: var(--panel);\n      border: 1px solid var(--line);\n      border-radius: 8px;\n      box-shadow: 0 14px 38px rgba(15, 23, 42, .08);\n      padding: 22px;\n    }\n    .metric {\n      color: var(--brand);\n      font-size: 30px;\n      font-weight: 900;\n      line-height: 1;\n    }\n    .label {\n      color: var(--muted);\n      font-size: 13px;\n      font-weight: 700;\n      margin-top: 8px;\n      text-transform: uppercase;\n    }\n    section {\n      margin-top: 26px;\n    }\n    h2 {\n      font-size: 24px;\n      margin: 0 0 14px;\n    }\n    ul {\n      margin: 0;\n      padding-left: 20px;\n    }\n    li {\n      margin: 9px 0;\n    }\n    .status {\n      border-left: 5px solid var(--ok);\n    }\n    .note {\n      color: var(--muted);\n      font-size: 14px;\n    }\n    code {\n      background: #eef1f5;\n      border: 1px solid #dde3eb;\n      border-radius: 4px;\n      padding: 2px 5px;\n    }\n    footer {\n      color: var(--muted);\n      font-size: 13px;\n      padding: 18px 24px 36px;\n      text-align: center;\n    }\n    @media (max-width: 820px) {\n      .grid { grid-template-columns: 1fr; margin-top: 20px; }\n      header { padding-top: 40px; }\n    }\n  </style>\n</head>\n<body>\n  <header>\n    <div class=\"wrap\">\n      <div class=\"eyebrow\">Phase 1 Published</div>\n      <h1>KTM Warehouse & Distribution Center</h1>\n      <p class=\"lead\">A public phase-1 publication page for the Laravel logistics platform, showing the security, payment, email, document privacy, and production-readiness work completed so far.</p>\n      <div class=\"actions\">\n        <a class=\"button primary\" href=\"https://github.com/kirannetpack-ui/kwdc\">View GitHub Repository</a>\n        <a class=\"button\" href=\"https://github.com/kirannetpack-ui/kwdc/commits/production-readiness-reminders-notifications\">View Phase 1 Commits</a>\n      </div>\n    </div>\n  </header>\n  <main>\n    <div class=\"grid\">\n      <div class=\"panel\">\n        <div class=\"metric\">160</div>\n        <div class=\"label\">PHPUnit tests passing</div>\n      </div>\n      <div class=\"panel\">\n        <div class=\"metric\">0</div>\n        <div class=\"label\">npm audit vulnerabilities</div>\n      </div>\n      <div class=\"panel\">\n        <div class=\"metric\">Phase 1</div>\n        <div class=\"label\">Published status</div>\n      </div>\n    </div>\n    <section class=\"panel status\">\n      <h2>Current Status</h2>\n      <p>The project source is committed and pushed to GitHub on branch <code>production-readiness-reminders-notifications</code>. This phase-1 public page has been generated from the same repository so stakeholders can review progress immediately.</p>\n      <p class=\"note\">The full application is a Laravel/PHP platform and still needs a Laravel-capable production host, database, queue worker, scheduler, mail provider, storage, and payment provider credentials before real customer traffic should use it end to end.</p>\n    </section>\n    <section class=\"panel\">\n      <h2>Completed Work</h2>\n      <ul>\n        <li>Configured production deployment guardrails and preflight checks for required environment, mail, session, HTTPS, database, and payment settings.</li>\n        <li>Removed inactive authentication scaffolding and kept one canonical password reset flow.</li>\n        <li>Added professional security emails for password reset and verification-style flows, including clear anti-phishing guidance.</li>\n        <li>Hardened payment provider sessions for Khalti and eSewa with configuration guards, timeouts, retries, amount validation, malformed-response handling, UUID transaction IDs, idempotent callbacks, and receipt generation fixes.</li>\n        <li>Restored invoice PDF generation with a production-ready invoice PDF template and tested invoice creation for payable records.</li>\n        <li>Protected dispatch PDF downloads, warehouse PDFs, dispatch stop invoice documents, stock documents, equipment compliance documents, warehouse request documents, box documents, and driver vehicle compliance documents behind private authorization routes.</li>\n        <li>Hardened dispatch ownership and tracking by preventing client spoofing, requiring owners/drivers/admins for actions, and using tokenized public tracking links.</li>\n        <li>Scoped security agency resources so agencies cannot modify another agency account or records.</li>\n        <li>Validated admin update payloads to prevent mass assignment of protected fields.</li>\n        <li>Added regression tests across security, payments, invoices, dispatch, documents, authentication, and production hardening.</li>\n        <li>Verified the current phase with PHPUnit, Composer audit/validation, npm audit, Vite build, and whitespace checks.</li>\n      </ul>\n    </section>\n    <section class=\"panel\">\n      <h2>Verification</h2>\n      <ul>\n        <li><code>php tools/composer.phar test</code> passed: 160 tests, 675 assertions, 1 skipped.</li>\n        <li><code>php tools/composer.phar audit</code> found no security vulnerability advisories.</li>\n        <li><code>php tools/composer.phar validate --strict --no-interaction</code> passed.</li>\n        <li><code>npm audit --audit-level=moderate</code> found 0 vulnerabilities.</li>\n        <li><code>npm run build</code> completed successfully.</li>\n        <li><code>git diff --check</code> passed.</li>\n      </ul>\n    </section>\n  </main>\n  <footer>\n    KTM-WDC Phase 1 publication. Generated from the production-readiness branch.\n  </footer>\n</body>\n</html>";

